using System.Windows.Forms;

public class MainForm : Form
{
    private StatusStrip statusStrip;

    public MainForm()
    {
        statusStrip = new StatusStrip();
        // .NET 9 breaking change: StatusStrip default RenderMode changed.
        // Explicitly set to preserve .NET 8 appearance.
        statusStrip.RenderMode = ToolStripRenderMode.ManagerRenderMode;

        statusStrip.Items.Add(new ToolStripStatusLabel("Ready"));
        Controls.Add(statusStrip);
    }
}

using System;
using System.ComponentModel;
using System.Drawing.Design;
using System.Windows.Forms;
using System.Windows.Forms.Design;

public class MyEditor : UITypeEditor
{
    public override object EditValue(ITypeDescriptorContext context,
        IServiceProvider provider, object value)
    {
        var editorService = provider?.GetService(typeof(IWindowsFormsEditorService))
            as IWindowsFormsEditorService;

        if (editorService == null)
            return value;

        var control = CreateEditorControl(value);

        // .NET 9 breaking change: DropDownControl now throws ArgumentNullException
        // if passed null. Guard against it.
        if (control != null)
        {
            editorService.DropDownControl(control);
            value = GetValueFromControl(control);
        }

        return value;
    }

    private Control CreateEditorControl(object currentValue)
    {
        // May return null depending on state
        if (currentValue == null)
            return null;

        var listBox = new ListBox();
        listBox.Items.Add(currentValue);
        return listBox;
    }

    private object GetValueFromControl(Control control)
    {
        if (control is ListBox lb && lb.SelectedItem != null)
            return lb.SelectedItem;
        return null;
    }

    public override UITypeEditorEditStyle GetEditStyle(ITypeDescriptorContext context)
    {
        return UITypeEditorEditStyle.DropDown;
    }
}

